	"ENQUEUE_JOB" NUMBER(*,0) NOT NULL ENABLE, 
	"SMIME" NUMBER(*,0) NOT NULL ENABLE, 
	"DONT_SEND_ON_ERROR" NUMBER(*,0) NOT NULL ENABLE, 
	"PRIVATE_KEY" VARCHAR2(255 CHAR), 
	"PRIVATE_KEY_PASSWORD" VARCHAR2(255 CHAR), 
	"CERTIFICATE" VARCHAR2(255 CHAR), 
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE
   );

CREATE TABLE "SUBSCRIPTION" 
   (	"ID" NUMBER(*,0) NOT NULL ENABLE, 
	"APPLICATION" VARCHAR2(80 CHAR), 
	"FOR_NAME" VARCHAR2(80 CHAR) NOT NULL ENABLE, 
	"FOR_ADDRESS" VARCHAR2(128 CHAR), 
	"FOR_EMAIL" VARCHAR2(128 CHAR) NOT NULL ENABLE, 
	"FOR_PHONE" VARCHAR2(50 CHAR) NOT NULL ENABLE, 
	"FOR_URL" VARCHAR2(80 CHAR), 
	"FOR_COMMENT" VARCHAR2(255 CHAR), 
	"BY_NAME" VARCHAR2(50 CHAR) NOT NULL ENABLE, 
	"BY_EMAIL" VARCHAR2(128 CHAR) NOT NULL ENABLE, 
	"BY_ADDRESS" VARCHAR2(128 CHAR), 
	"BY_PHONE" VARCHAR2(50 CHAR), 
	"BY_URL" VARCHAR2(80 CHAR), 
	"DATE_FROM" TIMESTAMP (6), 
	"DATE_TILL" TIMESTAMP (6), 
	"NUM_USERS" NUMBER(*,0), 
	"NUM_TOKENS" NUMBER(*,0), 
	"NUM_CLIENTS" NUMBER(*,0), 
	"level" VARCHAR2(80 CHAR), 
	"SIGNATURE" VARCHAR2(640 CHAR), 
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE
   );

CREATE TABLE "TOKEN" 
   (	"ID" NUMBER(*,0) NOT NULL ENABLE, 
	"DESCRIPTION" VARCHAR2(80 CHAR), 
	"SERIAL" VARCHAR2(40 CHAR) NOT NULL ENABLE, 
	"TOKENTYPE" VARCHAR2(30 CHAR), 
	"USER_PIN" VARCHAR2(512 CHAR), 
	"USER_PIN_IV" VARCHAR2(32 CHAR), 
	"SO_PIN" VARCHAR2(512 CHAR), 
	"SO_PIN_IV" VARCHAR2(32 CHAR), 
	"PIN_SEED" VARCHAR2(32 CHAR), 
	"OTPLEN" NUMBER(*,0), 
	"PIN_HASH" VARCHAR2(512 CHAR), 
	"KEY_ENC" VARCHAR2(2800 CHAR), 
	"KEY_IV" VARCHAR2(32 CHAR), 
	"MAXFAIL" NUMBER(*,0), 
	"ACTIVE" NUMBER(*,0) NOT NULL ENABLE, 
	"REVOKED" NUMBER(*,0), 
	"LOCKED" NUMBER(*,0), 
	"FAILCOUNT" NUMBER(*,0), 
	"COUNT" NUMBER(*,0), 
	"COUNT_WINDOW" NUMBER(*,0), 
	"SYNC_WINDOW" NUMBER(*,0), 
	"ROLLOUT_STATE" VARCHAR2(10 CHAR), 
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE
   );

CREATE TABLE "TOKENCONTAINER" 
   (	"ID" NUMBER(*,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TYPE" VARCHAR2(100 CHAR) NOT NULL ENABLE, 
	"DESCRIPTION" VARCHAR2(1024 CHAR), 
	"SERIAL" VARCHAR2(40 CHAR) NOT NULL ENABLE, 
	"LAST_SEEN" TIMESTAMP (6), 
	"LAST_UPDATED" TIMESTAMP (6), 
	"TEMPLATE_ID" NUMBER(*,0), 
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE
   );

CREATE TABLE "TOKENCONTAINERINFO" 
   (	"ID" NUMBER(*,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"KEY" VARCHAR2(255 CHAR) NOT NULL ENABLE, 
	"VALUE" CLOB, 
	"TYPE" VARCHAR2(100 CHAR), 
	"DESCRIPTION" VARCHAR2(2000 CHAR), 
	"CONTAINER_ID" NUMBER(*,0), 
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE, 
